738	   * This test passes that exact realistic combination and checks BOTH rules survive together in
739	   * the one shared `[DESKTOP_QUERY]` block.
740	   */
741	  test('sizeSelectorUnavailable and hideBagOnMobile together (the real unavailable-PLP shape) both survive in the same shared [DESKTOP_QUERY] block', () => {
742	    const style = ZimmProductCardRecipe.baseStyle({ sizeSelectorUnavailable: true, hideBagOnMobile: true });
743	    const root = style.root as Record<string, unknown>;
744	    const desktopBlock = root[DESKTOP_QUERY] as Record<string, unknown>;
745	    expect((desktopBlock[PRICE_KEY] as Record<string, unknown>).display).toBe('block');
746	    expect((desktopBlock[BAG_KEY] as Record<string, unknown>).display).toBe('flex');
747	  });
748	});
749	
750	/**
751	 * Fix C — DOM-level proof, same reasoning as Fix 1's own block below: an object-shape assertion
752	 * proves this recipe's `sizeSelectorUnavailable` key looks right in isolation, but not that a real
753	 * `[data-card-slot="sizeChips"]` element composed under the real generated root class actually
754	 * resolves to `display: none` once Emotion's cascade runs for real. Composes the real root recipe
755	 * (unavailable-PLP shape) with a bare marker div for the size-chips slot, through the real
756	 * (unmocked) `chakra` factory, and reads the jsdom-resolved value back via `getComputedStyle`.
757	 */
758	describe('ZimmProductCard — Fix C: size-chip wrapper is genuinely hidden when unavailable, not just un-revealed', () => {
759	  test('a real [data-card-slot="sizeChips"] element, composed under the real unavailable-PLP root recipe, resolves to display:none', () => {
760	    const rootStyle = ZimmProductCardRecipe.baseStyle({
761	      hoverHidesPrice: false,
762	      hoverRevealsPrice: false,
763	      hoverRevealsSizeSelector: false,
764	      sizeSelectorUnavailable: true,
765	    }).root;
766	
767	    const { container } = render(
768	      <chakra.div __css={rootStyle}>
769	        <div data-card-slot="content">
770	          <div data-card-slot="sizeChips">size chips</div>
771	        </div>
772	      </chakra.div>,
773	    );
774	
775	    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
776	    expect(window.getComputedStyle(sizeChips).display).toBe('none');
777	  });
778	});
779	
780	/**
781	 * Fix 1 (Scorer rework round 1) — DOM-level proof, not just an object-shape assertion. The
782	 * "real recipe assertions" block above proves this organism's OWN recipe object has the right
783	 * shape, but the actual bug was a CASCADE interaction between TWO separate recipes
784	 * (ZimmProductCardMedia's `close` part and this organism's `root` part) converging on the SAME
785	 * DOM node — that can only be proven by actually composing both recipes' real output through the
786	 * real Chakra/Emotion pipeline and reading the browser-resolved (here, jsdom-resolved) value back
787	 * via `getComputedStyle`, the same two real recipe modules the block above already imports
788	 * directly (bypassing the flat useMultiStyleConfig mock at the top of this file). `chakra` is
789	 * imported normally at the top of this file rather than via `vi.importActual` because the
790	 * `vi.mock('@chakra-ui/react', ...)` factory only overrides `useMultiStyleConfig` and spreads
791	 * `...actual` for everything else — `chakra` was never mocked, so it is already the real,
792	 * Emotion-backed factory and genuinely injects CSS into the jsdom document.
793	 *
794	 * This only asserts `position`/`top`/`right` — plain declarative property values, not real layout
795	 * geometry. Per this file's own "KNOWN LIMITATION" docblock (above the click-wiring describe
796	 * block) and `.claude/rules/testing.md`, jsdom performs no real layout/paint/hit-testing, so this
797	 * cannot prove a real mouse click lands on this button rather than some overlapping element —
798	 * only a real-browser/Playwright/manual check can prove that. It CAN correctly resolve which of
799	 * two competing same-property declarations wins a cascade by specificity, which is exactly what
800	 * this bug was and is what this test targets.
801	 */
802	describe('ZimmProductCard — Fix 1 (Scorer rework round 1): close button stays visually pinned', () => {
803	  test('the real close-button recipe, composed under the real organism root recipe in an actual rendered DOM node, resolves to position:absolute / top:0 / right:0 — not knocked into flow by the root’s lift rule', () => {
804	    const rootStyle = ZimmProductCardRecipe.baseStyle({
805	      hoverHidesPrice: true,
806	      hoverRevealsPrice: false,
807	      hoverRevealsSizeSelector: true,
808	    }).root;
809	    const closeStyle = ZimmProductCardMediaRecipe.baseStyle().close;
810	
811	    // Reproduces the real app's exact shape: Media's own `close` part styles the button directly
812	    // (one generated class, applied via Media's own __css prop in its own file); this organism's
813	    // `root` recipe's `[data-card-slot="close"]` descendant+attribute selector is a SECOND,
814	    // higher-specificity rule reaching the same button from the organism's own generated class on
815	    // its ancestor `div`. Both are wired here via the real (unmocked) `chakra` factory, so the
816	    // actual Emotion CSS text these two recipes emit — and the actual cascade between them — is
817	    // what jsdom resolves, not a hand-simplified stand-in.
818	    const { container } = render(
819	      <chakra.div __css={rootStyle}>
820	        <chakra.button __css={closeStyle} data-card-slot="close">
821	          close
822	        </chakra.button>
823	      </chakra.div>,
824	    );
825	
826	    const button = container.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`) as HTMLElement;
827	    const computed = window.getComputedStyle(button);
828	    expect(computed.position).toBe('absolute');
829	    expect(computed.top).toBe('0px');
830	    expect(computed.right).toBe('0px');
831	  });
832	});
833	
834	/**
835	 * Fix 3 (found during the manual real-browser check performed after the round-2 Scorer PASS) —
836	 * DOM-level proof, same technique and same caveat as the Fix 1 block above: this proves the
837	 * CASCADE resolves to the right declarative `position`/`zIndex` VALUES on the real composed node,
838	 * not that a real click lands there. That second half is exactly what jsdom cannot do (see this
839	 * file's own "KNOWN LIMITATION" docblock) and exactly what the manual real-browser check that
840	 * found this bug in the first place was for — a real `elementsFromPoint` probe at the arrow
841	 * button's own centre, confirmed the fix restores it as the topmost hit target once applied.
842	 */
843	describe('ZimmProductCard — Fix 3: carousel wrapper stays positioned and gains zIndex, not knocked static by the lift rule', () => {
844	  test('the real carousel-part recipe, composed under the real organism root recipe in an actual rendered DOM node, resolves to position:absolute (from Media) + zIndex:1 (from this organism)', () => {
845	    const rootStyle = ZimmProductCardRecipe.baseStyle({}).root;
846	    const carouselStyle = ZimmProductCardMediaRecipe.baseStyle().carousel;
847	
848	    // Same real-composition technique as the Fix 1 block above: Media's own `carousel` part
849	    // styles the element directly (including its `transform: translateY(-50%)` — the actual root
850	    // cause of this bug, see the docblock), and this organism's `root` recipe's
851	    // `[data-card-slot="carousel"]` descendant+attribute selector is a second rule reaching the
852	    // same element from the organism's own generated class on its ancestor `div`.
853	    const { container } = render(
854	      <chakra.div __css={rootStyle}>
855	        <chakra.div __css={carouselStyle} data-card-slot="carousel">
856	          carousel
857	        </chakra.div>
858	      </chakra.div>,
859	    );
860	
861	    const carousel = container.querySelector(`[data-card-slot="${CARD_SLOT.carousel}"]`) as HTMLElement;
862	    const computed = window.getComputedStyle(carousel);
863	    // Position comes from Media's own recipe, unclobbered — this organism's lift rule no longer
864	    // declares a competing `position` value here at all (see Fix 3 above).
865	    expect(computed.position).toBe('absolute');
866	    expect(computed.zIndex).toBe('1');
867	  });
868	});
869	
870	/**
871	 * Fix 2 (Scorer rework round 1) — DOM-level proof that the `:has(:focus-visible)` reveal genuinely
872	 * engages on a real focus event, not just that the recipe object carries the right string key
873	 * (already proven structurally in the "real recipe assertions" block above).
874	 *
875	 * IMPORTANT — this is `.matches()`-based, not `getComputedStyle()`-based, and that is a
876	 * deliberate, empirically-verified choice, not an oversight. This file's own "KNOWN LIMITATION"
877	 * docblock (above the click-wiring describe block) already establishes that jsdom performs no
878	 * real layout/paint/hit-testing; investigating this fix surfaced a SEPARATE, more specific jsdom
879	 * gap that docblock does not cover: `window.getComputedStyle()` in this project's installed jsdom
880	 * does not dynamically re-resolve a pseudo-class-gated rule after the DOM's focus state changes
881	 * post-mount, even for a bare self-referential `&:has(:focus-visible)` rule with no descendant
882	 * selector at all (confirmed by direct experiment — a real `.focus()` call correctly updates
883	 * `document.activeElement` and correctly makes `element.matches(':has(:focus-visible)')` return
884	 * `true`, but a subsequent `getComputedStyle()` read still reports the PRE-focus value). This is
885	 * exactly why Fix 1's proof above (a purely static cascade with no pseudo-class involved) could
886	 * safely use `getComputedStyle()` while this one cannot. `.matches()` against the exact literal
887	 * descendant-selector suffix the real recipe emits (`SIZE_CHIPS_KEY`, module-scope above) — with
888	 * only the Emotion-specific `&` swapped for a plain stand-in ancestor selector, since `&` is an
889	 * Emotion/PostCSS nesting token resolved at CSS-in-JS compile time, not a selector nwsapi
890	 * understands directly — correctly reflects the live DOM focus state both before and after a
891	 * real `.focus()` call, so it is what actually proves the mechanism here.
892	 *
893	 * jsdom has no concept of "focus triggered by a mouse click" vs "focus triggered by keyboard" —
894	 * there is no such distinction to probe — so this test proves the reveal still fires on real
895	 * focus, exactly as it did for `:focus-within`; it cannot prove, and only a real browser can,
896	 * that a mouse-click-focused button is excluded, which is the actual bug this fix (Fix H)
897	 * addresses.
898	 */
899	describe('ZimmProductCard — Fix 2 (Scorer rework round 1): size chips reveal on keyboard focus, not just mouse hover', () => {
900	  test('an ancestor :has(:focus-visible) + the real recipe’s own descendant-selector suffix flips from non-matching to matching once a nested control receives real focus', async () => {
901	    const user = userEvent.setup();
902	    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
903	    // Swap the Emotion-only `&` token for the stand-in ancestor selector above — the remaining,
904	    // actual descendant path comes straight from the real recipe's own module-scope constant,
905	    // not a hand-typed second copy.
906	    const revealSelector = FOCUS_VISIBLE_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);
907	
908	    const { container } = render(
909	      <div data-testid="card-root">
910	        <div data-card-slot="content">
911	          <button type="button">Add to bag</button>
912	          <div data-card-slot="sizeChips">size chips</div>
913	        </div>
914	      </div>,
915	    );
916	
917	    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
918	    // Before focus lands anywhere in the card, the reveal selector does not match — mirrors the
919	    // unconditional (outside-media-query) `display: none` default a touch/no-hover pointer sees
920	    // permanently in the real recipe.
921	    expect(sizeChips.matches(revealSelector)).toBe(false);
922	
923	    // Fix H rework: `await user.tab()` (a real simulated Tab keypress), not a bare `.focus()` call
924	    // (what this test used for the `:focus-within` version, and what a first pass at this rename
925	    // kept unchanged). Empirically, in THIS project's installed jsdom/nwsapi, a bare `.focus()`
926	    // call satisfies `:focus-visible` only when nothing else in the same test FILE has already
927	    // driven a real pointer-originated focus via `userEvent.click()` — Vitest's jsdom environment
928	    // is created once per file, not per test, so state can carry over. Confirmed by direct
929	    // experiment: this exact assertion passes when this test runs alone, and fails when it runs
930	    // after any of this file's own `user.click(...)` tests (e.g. the "bag button" test in the
931	    // click-wiring describe block above) — with `document.hasFocus()`/`document.activeElement`
932	    // still correctly pointing at this test's own button, but `button.matches(':focus-visible')`
933	    // alone (no `:has()`, no compound selector) already false. `:focus`/`:focus-within` are
934	    // unaffected either way. `await user.tab()` sidesteps this reliably (verified against both the
935	    // isolated case and the full 57-test file) and is arguably the more faithful simulation of
936	    // what this test claims to prove in the first place — a keyboard user tabbing into the card —
937	    // than an imperative `.focus()` call, which does not represent any particular input modality.
938	    await user.tab();
939	
940	    // :has(:focus-visible) on the card ROOT (not on the size-chip wrapper itself, which would be
941	    // circular — an element that is display:none is unfocusable and unreachable by Tab) bubbles
942	    // from this descendant's real focus state up to the root, so the reveal selector now matches
943	    // — the same live-DOM condition the real recipe's CSS rule keys its `display: block` off.
944	    expect(sizeChips.matches(revealSelector)).toBe(true);
945	  });
946	
947	  test('the reveal selector still does not match a sibling control receiving focus outside the card root entirely', async () => {
948	    const user = userEvent.setup();
949	    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
950	    const revealSelector = FOCUS_VISIBLE_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);
951	
952	    const { container } = render(
953	      <>
954	        <button type="button">Outside the card</button>
955	        <div data-testid="card-root">
956	          <div data-card-slot="content">
957	            <div data-card-slot="sizeChips">size chips</div>
958	          </div>
959	        </div>
960	      </>,
961	    );
962	
963	    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
964	    // Keyboard-originated focus via user.tab(), not a bare .focus() call — see the sibling test
965	    // above (lines ~923-937) for the full jsdom/nwsapi quirk this sidesteps: a bare .focus() call
966	    // only satisfies :focus-visible when nothing earlier in this test file has already driven a
967	    // real userEvent.click()-originated focus, which this file's own earlier describe blocks do.
968	    // Without this, the assertion below could pass vacuously — false because nothing has
969	    // :focus-visible at all by this point in the run, not because the selector genuinely excludes
970	    // focus outside the card root. The intermediate assertion confirms focus actually landed on
971	    // this element before the real thing under test is checked.
972	    await user.tab();
973	    expect(screen.getByRole('button', { name: 'Outside the card' })).toHaveFocus();
974	
975	    // Guards against a selector so loose it would match regardless of where focus actually is —
976	    // focus outside the card root must never trigger the reveal.
977	    expect(sizeChips.matches(revealSelector)).toBe(false);
978	  });
979	});
980	
981	/**
982	 * No `switch`/`if` on `props.variation` anywhere in this organism's render body (index.tsx) is
983	 * the extensibility AC's actual proof and is not practically assertable at runtime — a test could
984	 * only prove one execution path took/didn't take a branch, not that no such branch exists in the
985	 * source at all. Verified instead by direct inspection + a literal grep, reported alongside this
986	 * suite's results rather than encoded as a test:
987	 *
988	 *   grep -n "variation ===" index.tsx        -> no matches
989	 *   grep -n "switch (variation)" index.tsx   -> no matches
990	 *
991	 * Every layout/visibility decision in index.tsx instead reads from `VARIATION_CONFIG[variation]`
992	 * — a single object-property lookup, not a branching statement.
993	 */
994

