/**
 * Scoped per testing.md: this organism's own contract (given a variation + props, does it render
 * the right children with the right flags, and does every interactive control still fire its own
 * callback) — not ZimmProductCardMedia/ZimmProductCardContent's own internal logic, which is
 * already proven in their own index.test.tsx files. Both are composed for real here (not mocked
 * out), the same "costs nothing, gives real integration confidence" precedent
 * zimmProductCardContent/index.test.tsx already documents for its own composed atoms/molecules.
 *
 * Only `useMultiStyleConfig` is mocked, with one flat object covering every part every composed
 * descendant reads (`ZimmProductCardMedia`, `ZimmSlideIndicator`, `ZimmProductCardContent`,
 * `ZimmProductPrice`, `ZimmSizeChipGroup`, `ZimmSizeChip`, and this organism's own `root`) — same
 * "neither test setup nor Chakra cares which recipe name asked for it" precedent
 * zimmProductCardMedia/index.test.tsx documents. `ZimmProductName`'s `useStyleConfig` call is left
 * real/unmocked, same as zimmProductCardContent/index.test.tsx.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { chakra } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { ZimmProductCard } from './index';
import type {
  ZimmProductCardProps,
  ZimmProductCardImage,
  ZimmProductCardBaseProps,
  ZimmProductCardPlpVariation,
  ZimmProductCardHomeVariation,
  ZimmProductCardWishlistVariation,
} from './index';
import { ZimmProductCard as ZimmProductCardRecipe } from './zimmProductCard.css';
// Fix 1 (Scorer rework round 1): needed to compose the REAL close-part style object this
// organism's root recipe cascades against — see the "Fix 1" describe block below. `chakra` above
// is imported the normal way (not via vi.importActual) because the vi.mock('@chakra-ui/react', ...)
// factory below spreads `...actual` and only overrides `useMultiStyleConfig` — `chakra` itself
// was never mocked, so this import already resolves to the real Emotion-backed factory.
import { ZimmProductCardMedia as ZimmProductCardMediaRecipe } from '../../molecules/zimmProductCardMedia/zimmProductCardMedia.css';
// Fix D: the real `breakpoints.md` value, so DESKTOP_QUERY below can't drift from the source
// file's own derivation of it. No DOM-level compose-and-read proof for this one (unlike Fix 1/3/
// C above) — those all resolve a STATIC declaration; jsdom's actual support for resolving a real
// `min-width` media query against getComputedStyle is unreliable enough that the object-shape
// assertions below, plus the real-browser check every hover/pointer concern in this file's own
// "KNOWN LIMITATION" docblock already defers to, are the honest level of proof here.
import { breakpoints } from 'app/theme/foundation';
import { CARD_SLOT, HOVER_CAPABLE_QUERY } from '../../zimmProductCardShared';

/**
 * Fix G's own contribution is a boolean `index.tsx` COMPUTES (`bagHiddenOnMobile`, combining two
 * VARIATION_CONFIG fields with `isUnavailable`) before ever calling `useMultiStyleConfig` — the
 * "real recipe assertions" pattern used everywhere else in this file proves the RECIPE reacts
 * correctly to a given `hideBagOnMobile` value, but says nothing about whether index.tsx computed
 * the right value in the first place. `vi.hoisted` lets this mock factory (hoisted above the rest
 * of the file by Vitest) share a capture slot with the test body below, without hitting a TDZ
 * error from referencing an un-hoisted `let`.
 */
const { capturedOrganismStyleProps } = vi.hoisted(() => ({
  capturedOrganismStyleProps: { current: undefined as Record<string, unknown> | undefined },
}));

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: (recipeName: string, props?: Record<string, unknown>) => {
      if (recipeName === 'ZimmProductCard') {
        capturedOrganismStyleProps.current = props;
      }
      return {
        // This organism's own recipe.
        root: {},
        // ZimmProductCardMedia.
        scrollContainer: {},
        slide: {},
        image: {},
        hoverSwapBase: {},
        hoverSwapOverlay: {},
        badge: {},
        badgeLabel: {},
        close: {},
        carousel: {},
        arrowButton: {},
        indicatorWrapper: {},
        // ZimmSlideIndicator.
        dot: {},
        // ZimmProductCardContent.
        nameRow: {},
        nameLink: {},
        bagWrapper: {},
        bagButton: {},
        attributesRow: {},
        colourText: {},
        sizeText: {},
        priceWrapper: {},
        sizeChipWrapper: {},
        notifyMeButton: {},
        // ZimmProductPrice.
        container: {},
        wasPrice: {},
        nowPrice: {},
        // ZimmSizeChipGroup.
        radiogroup: {},
        oneSize: {},
        // ZimmSizeChip.
        chip: {},
      };
    },
  };
});

// ZimmIcon (used by ZimmProductCardContent's bag button) and the icons barrel (used by
// ZimmProductCardMedia's close/arrow buttons): known Vitest SVG side-effect issue documented in
// .claude/rules/testing.md's "Known gap: ZimmIcon throws under Vitest". Mocked at the same
// resolved module each consumer imports — both consumers sit at the same depth below `ui-kits/`
// as this test file, so the relative specifiers are identical to what
// zimmProductCardContent/index.test.tsx and zimmProductCardMedia/index.test.tsx use themselves.
vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
vi.mock('../../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
  CloseIcon: () => null,
}));

const wrap = (ui: React.ReactElement) =>
  render(
    <MemoryRouter>
      <IntlProvider locale="en" defaultLocale="en">
        {ui}
      </IntlProvider>
    </MemoryRouter>,
  );

const PRIMARY: ZimmProductCardImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
const HOVER: ZimmProductCardImage = { src: 'hover.jpg', alt: 'Zimmermann dress, on model' };
const GALLERY: ZimmProductCardImage[] = [
  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
];

const SIZES = [
  { value: 'xs', label: 'XS' },
  { value: 's', label: 'S' },
];

/**
 * Module-scope (not describe-block-local) so both the "real recipe assertions" describe block
 * below AND the Fix 1 / Fix 2 (Scorer rework round 1) DOM-level proof blocks further down can
 * share one definition rather than each hand-duplicating the same literal selector strings.
 */
const STRETCH_KEY = `[data-card-slot="${CARD_SLOT.content}"] a::after`;
const CLOSE_LIFT_KEY = `[data-card-slot="${CARD_SLOT.close}"]`;
const CAROUSEL_LIFT_KEY = `[data-card-slot="${CARD_SLOT.carousel}"]`;
// Behavioural fix: the carousel arrow reveal (docblock point 6) — unlike every other reveal key
// below, these two are unconditional (no gating flag), so they're built straight off
// CAROUSEL_LIFT_KEY rather than a nested `[data-card-slot="content"] ...` path — the carousel
// wrapper is a direct child of Media's own root, a sibling of `content`, not nested under it.
const HOVER_CAROUSEL_KEY = `&:hover ${CAROUSEL_LIFT_KEY}`;
const FOCUS_VISIBLE_CAROUSEL_KEY = `&:has(:focus-visible) ${CAROUSEL_LIFT_KEY}`;
const CONTENT_LIFT_KEY = `[data-card-slot="${CARD_SLOT.content}"] button`;
const PRICE_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.price}"]`;
const SIZE_CHIPS_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.sizeChips}"]`;
const HOVER_PRICE_KEY = `&:hover ${PRICE_KEY}`;
const HOVER_SIZE_CHIPS_KEY = `&:hover ${SIZE_CHIPS_KEY}`;
// Fix 2 (Scorer rework round 1): the keyboard-reachable equivalent of each hover-reveal rule
// above — see this file's own docblock note on the compound-selector vs separate-key idiom
// question, resolved by reading zimmSearchInput.css.ts and globalStyles.ts's zimmFormRow/
// zimmFormRowInverse: both use a separate sibling key (`_focusWithin` alongside `_hover`), never
// a comma-joined compound selector. This file already uses raw selector strings (not Chakra's
// `_hover`/`_focusWithin` shorthand props) because the hover rules need a descendant-combinator
// path baked into the selector itself, so the equivalent here is a separate `'&:has(:focus-visible) ...'`
// string key alongside the existing `'&:hover ...'` key, not a merged `'&:hover, &:has(:focus-visible) ...'`
// selector.
const FOCUS_VISIBLE_PRICE_KEY = `&:has(:focus-visible) ${PRICE_KEY}`;
const FOCUS_VISIBLE_SIZE_CHIPS_KEY = `&:has(:focus-visible) ${SIZE_CHIPS_KEY}`;
// Fix C: notify-me's own reveal-key trio, all three living INSIDE the HOVER_CAPABLE_QUERY block
// (see zimmProductCard.css.ts docblock point 4 for why this is the opposite structure from price/
// size-chips above — the "hidden by default" half must not be reachable by a touch pointer).
const NOTIFY_ME_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.notifyMe}"]`;
const HOVER_NOTIFY_ME_KEY = `&:hover ${NOTIFY_ME_KEY}`;
const FOCUS_VISIBLE_NOTIFY_ME_KEY = `&:has(:focus-visible) ${NOTIFY_ME_KEY}`;
// Fix D: the PLP-only bag-icon mobile hide — a viewport-width gate, not a hover one (see
// zimmProductCard.css.ts docblock point 5). Built from the real `breakpoints` import (not a
// hand-typed literal) so this can't silently drift from what the source file actually emits —
// `breakpoints.md` is `'48em'`, not a `768px` string, despite that being its px-equivalent value.
const DESKTOP_QUERY = `@media (min-width: ${breakpoints.md})`;
const BAG_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.bag}"]`;

/** Mocks the scroll container's native `scrollTo` (absent under jsdom), same technique as
 *  zimmProductCardMedia/index.test.tsx's own mockScrollTo. */
const mockScrollTo = (): ReturnType<typeof vi.fn> => {
  const scrollContainer = screen.getByTestId('card-media-scroll');
  const scrollTo = vi.fn();
  scrollContainer.scrollTo = scrollTo;
  return scrollTo;
};

/**
 * A complete, valid props object for a given variation — narrows on `variation` with a plain
 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
 * index.tsx's own render body, not to test fixtures).
 *
 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
 * present on every union member." A `test.each` call site passing a runtime (non-literal)
 * `variation` still resolves to the final, general overload below.
 */
function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
  const base = {
    id: 'p1',
    href: '/product/1',
    name: 'Natura Dress',
    headingLevel: 'h3' as const,
    primaryImage: PRIMARY,
  };
  switch (variation) {
    case 'wishlist':
      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
    case 'home':
      return { ...base, variation };
    case 'plp':
      return { ...base, variation };
    default:
      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
      // not silently falls through to a wrong variation's shape.
      return ((): never => {
        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
      })();
  }
}

describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
  // so the object still constructs and runs at test time regardless of what `tsc` says about it.
  test('wishlist variation requires onRemove, colour and size (type-only)', () => {
    // @ts-expect-error — wishlist requires onRemove, colour and size; none are supplied here.
    const invalid: ZimmProductCardProps = {
      id: 'p1',
      href: '/product/1',
      name: 'Dress',
      headingLevel: 'h3',
      primaryImage: PRIMARY,
      variation: 'wishlist',
    };
    expect(invalid).toBeDefined();
  });

  test('home variation does not accept onRemove (type-only)', () => {
    // Assigned to the narrow per-variation intersection, not the `ZimmProductCardProps` union
    // alias: TypeScript's excess-property check on a *union* target only flags a property as
    // excess when it is unknown to EVERY member, so `onRemove` (valid on the wishlist member)
    // would silently pass here even under `variation: 'home'` if assigned to the union type
    // directly — confirmed empirically while building this test (an earlier version of this
    // exact case, assigned to `ZimmProductCardProps`, produced an "unused @ts-expect-error"
    // compile error because of this). The narrow intersection has no such escape hatch: it is a
    // plain object type with no `onRemove` key anywhere, so the excess property is genuinely
    // unknown and TypeScript reports it.
    //
    // The directive sits directly above the `onRemove` line, not the `const invalid = {` line
    // above it: TS anchors this specific "object literal may only specify known properties"
    // diagnostic to the offending property's own line, and `@ts-expect-error` only suppresses
    // (and only counts as "used" for) a diagnostic reported on the *immediate next* line.
    const invalid: ZimmProductCardBaseProps & ZimmProductCardHomeVariation = {
      id: 'p2',
      href: '/product/1',
      name: 'Dress',
      headingLevel: 'h3',
      primaryImage: PRIMARY,
      variation: 'home',
      // @ts-expect-error — onRemove does not exist on the home variation's own shape.
      onRemove: () => {},
    };
    expect(invalid).toBeDefined();
  });
});

