import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router-dom';
import { IntlProvider } from 'react-intl';
import { ZimmColourSwatchGroup } from './index';
import type { ZimmColourSwatchValue } from './index';

// ZimmColourSwatch renders a <Link> which needs a Router, and its atom recipe needs
// useMultiStyleConfig — mock both layers so tests don't require a full Chakra theme.
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({ root: {}, label: {}, labelName: {}, swatches: {}, pagination: {}, pageButton: {} }),
  };
});

// ChevronLeftIcon / ChevronRightIcon: icons barrel has the Vitest SVG side-effect issue.
vi.mock('../../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
}));

const IMG = 'https://example.test/swatch.jpg';

const val = (value: string, name: string, over: Partial<ZimmColourSwatchValue> = {}): ZimmColourSwatchValue => ({
  value,
  name,
  imageUrl: IMG,
  href: `/product/p?color=${value}`,
  orderable: true,
  ...over,
});

const THREE = [val('a', 'Alpha'), val('b', 'Bravo'), val('c', 'Charlie')];
const FIVE = [val('a', 'Alpha'), val('b', 'Bravo'), val('c', 'Charlie'), val('d', 'Delta'), val('e', 'Echo')];

const wrap = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en" defaultLocale="en">
      <MemoryRouter>{ui}</MemoryRouter>
    </IntlProvider>,
  );
const group = () => screen.getByRole('radiogroup', { name: 'Colour' });
const radios = () => screen.getAllByRole('radio');

describe('ZimmColourSwatchGroup — no offered colours', () => {
  test('renders nothing when every value fails the imageUrl/orderable filter', () => {
    const { container } = wrap(
      <ZimmColourSwatchGroup
        values={[val('a', 'Alpha', { imageUrl: undefined }), val('b', 'Bravo', { orderable: false })]}
      />,
    );

